import{_ as t,o as a,c as r,b6 as l}from"./chunks/framework.BUXTSoD9.js";const f=JSON.parse('{"title":"Presentation du projet","description":"","frontmatter":{},"headers":[],"relativePath":"fr-fr/guide/introduction.md","filePath":"fr-fr/guide/introduction.md"}'),n={name:"fr-fr/guide/introduction.md"};function i(s,e,d,o,p,u){return a(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="presentation-du-projet" tabindex="-1">Presentation du projet <a class="header-anchor" href="#presentation-du-projet" aria-label="Permalink to “Presentation du projet”">​</a></h1><p>En 2025, de nombreuses personnes considèrent cette année comme le point de départ de la programmation par IA. De plus en plus de gens commencent à utiliser l&#39;IA pour écrire du code, mais les résultats restent souvent au stade de prototype -- sans savoir comment organiser un processus de développement avec le Vibe Coding, quels outils choisir, et encore moins quelles étapes clés séparent le prototype de la mise en production.</p><p>Nous adoptons une <strong>approche pratique en trois étapes</strong> : l&#39;étape débutant permet de se familiariser rapidement avec la programmation par IA grâce à des mini-jeux ; la première étape permet de maîtriser le flux de travail du Vibe Coding et de réaliser un prototype d&#39;application Web ; la deuxième étape couvre le développement full-stack et le déploiement en production ; la troisième étape permet de construire des applications complexes multiplateformes.</p><p>Chaque étape est accompagnée d&#39;un projet pratique complet, vous permettant de passer du prototype au produit grâce à des défis concrets, et d&#39;acquérir finalement la capacité à <strong>transformer n&#39;importe quelle idée en une application fonctionnelle</strong>.</p><p>Nous sommes convaincus qu&#39;en maîtrisant le Vibe Coding associé à une formation systématique, vous pouvez devenir à vous seul un <strong>développeur polyvalent, combinant développement front-end et back-end, intégration de capacités IA et conception de produits</strong>.</p><p>Ce projet s&#39;adresse principalement à trois types d&#39;apprenants :</p><ul><li><strong>Débutants (grand public / côté produit et operations)</strong> : aider les profils non techniques et les apprenants débutants à comprendre les concepts clés et à réaliser un premier petit outil IA ou prototype de produit.</li><li><strong>Développeurs intermédiaires (étudiants et développeurs ayant quelques bases)</strong> : maîtriser systématiquement le Vibe Coding et le développement d&#39;applications IA natives.</li><li><strong>Développeurs avancés (entreprises et startups, open source et développeurs indépendants)</strong> : accompagner les équipes et les individus dans la création, la validation et l&#39;itération rapide d&#39;applications IA natives.</li></ul><h2 id="📖-navigation-du-contenu" tabindex="-1">📖 Navigation du contenu <a class="header-anchor" href="#📖-navigation-du-contenu" aria-label="Permalink to “📖 Navigation du contenu”">​</a></h2><h3 id="appendice-general" tabindex="-1">Appendice général <a class="header-anchor" href="#appendice-general" aria-label="Permalink to “Appendice général”">​</a></h3><p><a href="/easy-vibe-ja-learning-map/fr-fr/appendix/8-artificial-intelligence/ai-capability-dictionary.html">Dictionnaire des capacités IA : explication des concepts clés, termes et scénarios courants</a></p><h3 id="etape-0-maternelle" tabindex="-1">Étape 0 : Maternelle <a class="header-anchor" href="#etape-0-maternelle" aria-label="Permalink to “Étape 0 : Maternelle”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/learning-map/">Guide debutant : carte d&#39;apprentissage</a></td><td style="text-align:left;">Aperçu global du parcours d&#39;apprentissage</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/ai-capabilities-through-games/">Guide debutant : À l&#39;ère de l&#39;IA, savoir parler, c&#39;est savoir coder</a></td><td style="text-align:left;">Découvrir les capacités de la programmation IA grâce à des exemples comme le jeu du serpent</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="etape-1-chef-de-produit-ia" tabindex="-1">Étape 1 : Chef de produit IA <a class="header-anchor" href="#etape-1-chef-de-produit-ia" aria-label="Permalink to “Étape 1 : Chef de produit IA”">​</a></h3><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/introduction-to-ai-ide/">Niveau 1 chapitre 2 : Decouvrir les outils AI IDE</a></td><td style="text-align:left;">Apprendre à utiliser un IDE, maîtriser la structure de l&#39;interface et les méthodes de prompting efficaces</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/building-prototype/">Niveau 1 chapitre 3 : Creer un prototype</a></td><td style="text-align:left;">De l&#39;analyse produit au prototype multipage, un cycle complet</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/integrating-ai-capabilities/">Niveau 1 chapitre 4 : Ajouter des capacites IA au prototype</a></td><td style="text-align:left;">Comprendre et intégrer les API de capacités IA courantes (texte, image, vidéo)</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/complete-project-practice/">Niveau 1 chapitre 5 : Projet complet pratique</a></td><td style="text-align:left;">Simuler des scénarios réels, itérer à partir des retours utilisateurs et finaliser la présentation du projet (projet de fin de parcours inclus)</td><td style="text-align:left;">✅</td></tr></tbody></table><h4 id="annexes" tabindex="-1">Annexes <a class="header-anchor" href="#annexes" aria-label="Permalink to “Annexes”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-a-product-thinking/">Annexe A : Complement sur la pensee produit</a></td><td style="text-align:left;">Du cadrage des idées à la réflexion produit en passant par le MVP</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-b-common-errors/">Annexe B : Erreurs courantes et solutions</a></td><td style="text-align:left;">Erreurs fréquentes en Vibe Coding et méthodes de dépannage</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-idea-sources/">Annexe : Ou trouver des idees</a></td><td style="text-align:left;">Identifier des directions à partir d&#39;applications de référence, de tendances et de listes de VC</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-double-diamond/">Annexe : Le modele Double Diamond</a></td><td style="text-align:left;">Comprendre le rythme complet : définir d&#39;abord le problème, puis concevoir la solution</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-jobs-to-be-done/">Annexe : Jobs to Be Done</a></td><td style="text-align:left;">Utiliser la méthode JTBD pour comprendre ce que l&#39;utilisateur veut vraiment accomplir</td><td style="text-align:left;">✅</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-1/appendix-mom-test/">Annexe : The Mom Test - Entretiens utilisateurs</a></td><td style="text-align:left;">Méthode de recherche pour valider les besoins via des entretiens utilisateurs</td><td style="text-align:left;">✅</td></tr></tbody></table><h3 id="etape-2-developpeur-intermediaire" tabindex="-1">Étape 2 : Développeur intermédiaire <a class="header-anchor" href="#etape-2-developpeur-intermediaire" aria-label="Permalink to “Étape 2 : Développeur intermédiaire”">​</a></h3><h4 id="partie-front-end" tabindex="-1">Partie front-end <a class="header-anchor" href="#partie-front-end" aria-label="Permalink to “Partie front-end”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;">Utiliser lovart pour produire des ressources</td><td style="text-align:left;">Apprendre à utiliser lovart pour générer en masse des visuels (personnages, décors, etc.), fournissant une base de ressources pour le design UI et le développement front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Introduction à Figma et MasterGo</td><td style="text-align:left;">Utiliser les outils de design pour structurer l&#39;architecture de l&#39;information et la mise en page, posant les bases de l&#39;implémentation front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Construire une premiere application moderne - Design UI</td><td style="text-align:left;">Réaliser une interface basée sur les composants à partir des maquettes, établissant le premier lien entre design et code</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Concevoir des pages et boutons selon les normes UI</td><td style="text-align:left;">Apprendre à organiser la structure des pages et la hiérarchie des boutons selon les standards de design dominants, et utiliser l&#39;IA pour générer des propositions</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-2/frontend/hogwarts-portraits/">Creer des portraits de Poudlard ensemble</a></td><td style="text-align:left;">Créer de A à Z une application front-end intégrant des capacités IA, en combinant design et développement</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="partie-back-end" tabindex="-1">Partie back-end <a class="header-anchor" href="#partie-back-end" aria-label="Permalink to “Partie back-end”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;">Qu&#39;est-ce qu&#39;une API</td><td style="text-align:left;">Comprendre les interfaces HTTP et le modèle requête/réponse, en préparation de l&#39;intégration et des tests back-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-2/backend/database-supabase/">De la base de données à Supabase</a></td><td style="text-align:left;">Implémenter une base de données et une API sur Supabase, relier le modèle de données aux pages front-end</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Rediger du code d&#39;interface et de la documentation assistee par LLM</td><td style="text-align:left;">Utiliser les LLM pour générer du code d&#39;interface et de la documentation de base de données, réalisant un back-end lisible et testable</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Flux de travail Git et deploiement Zeabur</td><td style="text-align:left;">Gérer le code avec un flux Git et déployer l&#39;application sur Zeabur pour la mise en production</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Outils de développement CLI modernes</td><td style="text-align:left;">Utiliser les outils CLI de programmation IA pour accélérer le développement et le débogage, et établir un flux de travail personnel industrialisé</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Comment integrer un systeme de paiement comme stripe</td><td style="text-align:left;">Intégrer un système de paiement et compléter le circuit de facturation et le processus de règlement de base</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Construire une premiere application moderne - Application full-stack</td><td style="text-align:left;">Combiner front-end, back-end et module de paiement pour livrer une application Web full-stack déployable</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Bibliotheque de composants front-end modernes + Trae en pratique</td><td style="text-align:left;">Utiliser une bibliothèque de composants front-end modernes et Trae pour réaliser de manière autonome un produit avec connexion/inscription et support de paiement</td><td style="text-align:left;">🚧</td></tr></tbody></table><h4 id="appendice-capacites-ia" tabindex="-1">Appendice capacites IA <a class="header-anchor" href="#appendice-capacites-ia" aria-label="Permalink to “Appendice capacites IA”">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">Chapitre</th><th style="text-align:left;">Contenu clé</th><th style="text-align:left;">Statut</th></tr></thead><tbody><tr><td style="text-align:left;"><a href="/easy-vibe-ja-learning-map/fr-fr/stage-2/ai-capabilities/dify-knowledge-base/">Introduction à Dify et integration de base de connaissances</a></td><td style="text-align:left;">Créer un produit de type outil avec Dify Workflow et un RAG basique, en préparation des évolutions futures de l&#39;application</td><td style="text-align:left;">🚧</td></tr><tr><td style="text-align:left;">Apprendre à consulter le dictionnaire IA et integrer des API multimodales</td><td style="text-align:left;">Apprendre à trouver les modèles et API appropriés, et intégrer les capacités multimodales (texte, image, etc.) dans le produit</td><td style="text-align:left;">🚧</td></tr></tbody></table><h3 id="etape-3-developpeur-avance" tabindex="-1">Étape 3 : Développeur avancé <a class="header-anchor" href="#etape-3-developpeur-avance" aria-label="Permalink to “Étape 3 : Développeur avancé”">​</a></h3>',24)])])}const g=t(n,[["render",i]]);export{f as __pageData,g as default};
